@Test
public void testRackAwarePolicy() throws IOException {
    conf.set(ScmConfigKeys.OZONE_SCM_CONTAINER_PLACEMENT_IMPL_KEY, SCMContainerPlacementRackAware.class.getName());
    NodeSchema[] schemas = new NodeSchema[] { ROOT_SCHEMA, RACK_SCHEMA, LEAF_SCHEMA };
    NodeSchemaManager.getInstance().init(schemas, true);
    cluster = new NetworkTopologyImpl(NodeSchemaManager.getInstance());
    // build datanodes, and network topology
    String rack = "/rack";
    String hostname = "node";
    for (int i = 0; i < 15; i++) {
        // Totally 3 racks, each has 5 datanodes
        DatanodeDetails node = MockDatanodeDetails.createDatanodeDetails(hostname + i, rack + (i / 5));
        datanodes.add(node);
        cluster.add(node);
    }
    // create mock node manager
    nodeManager = Mockito.mock(NodeManager.class);
    when(nodeManager.getNodes(NodeState.HEALTHY)).thenReturn(new ArrayList<>(datanodes));
    when(nodeManager.getNodeStat(anyObject())).thenReturn(new SCMNodeMetric(storageCapacity, 0L, 100L));
    when(nodeManager.getNodeStat(datanodes.get(2))).thenReturn(new SCMNodeMetric(storageCapacity, 90L, 10L));
    when(nodeManager.getNodeStat(datanodes.get(3))).thenReturn(new SCMNodeMetric(storageCapacity, 80L, 20L));
    when(nodeManager.getNodeStat(datanodes.get(4))).thenReturn(new SCMNodeMetric(storageCapacity, 70L, 30L));
    ContainerPlacementPolicy policy = ContainerPlacementPolicyFactory.getPolicy(conf, nodeManager, cluster, true, SCMContainerPlacementMetrics.create());
    int nodeNum = 3;
    List<DatanodeDetails> datanodeDetails = policy.chooseDatanodes(null, null, nodeNum, 15);
    Assert.assertEquals(nodeNum, datanodeDetails.size());
    Assert.assertTrue(cluster.isSameParent(datanodeDetails.get(0), datanodeDetails.get(1)));
    Assert.assertFalse(cluster.isSameParent(datanodeDetails.get(0), datanodeDetails.get(2)));
    Assert.assertFalse(cluster.isSameParent(datanodeDetails.get(1), datanodeDetails.get(2)));
}

