@Test
public void testLoadSnapshotInfoOnStart() throws Exception {
    // Stop the Ratis server and manually update the snapshotInfo.
    TermIndex oldSnaphsotIndex = ozoneManager.saveRatisSnapshot();
    ozoneManager.getSnapshotInfo().saveRatisSnapshotToDisk(oldSnaphsotIndex);
    omRatisServer.stop();
    TermIndex newSnapshotIndex = TermIndex.newTermIndex(oldSnaphsotIndex.getTerm(), oldSnaphsotIndex.getIndex() + 100);
    ozoneManager.getSnapshotInfo().saveRatisSnapshotToDisk(newSnapshotIndex);
    // Start new Ratis server. It should pick up and load the new SnapshotInfo
    omRatisServer = OzoneManagerRatisServer.newOMRatisServer(conf, ozoneManager, omNodeDetails, Collections.emptyList());
    omRatisServer.start();
    TermIndex lastAppliedTermIndex = omRatisServer.getLastAppliedTermIndex();
    Assert.assertEquals(newSnapshotIndex.getIndex(), lastAppliedTermIndex.getIndex());
    Assert.assertEquals(newSnapshotIndex.getTerm(), lastAppliedTermIndex.getTerm());
}

