@Test
public void testLookupFileWithDnFailure() throws IOException {
    final StorageContainerLocationProtocol containerClient = Mockito.mock(StorageContainerLocationProtocol.class);
    final KeyManager manager = new KeyManagerImpl(null, new ScmClient(Mockito.mock(ScmBlockLocationProtocol.class), containerClient), metadataManager, configuration, "test-om", Mockito.mock(OzoneBlockTokenSecretManager.class), null, null);
    final DatanodeDetails dnOne = MockDatanodeDetails.randomDatanodeDetails();
    final DatanodeDetails dnTwo = MockDatanodeDetails.randomDatanodeDetails();
    final DatanodeDetails dnThree = MockDatanodeDetails.randomDatanodeDetails();
    final DatanodeDetails dnFour = MockDatanodeDetails.randomDatanodeDetails();
    final DatanodeDetails dnFive = MockDatanodeDetails.randomDatanodeDetails();
    final DatanodeDetails dnSix = MockDatanodeDetails.randomDatanodeDetails();
    final Pipeline pipelineOne = Pipeline.newBuilder().setId(PipelineID.randomId()).setType(ReplicationType.RATIS).setFactor(ReplicationFactor.THREE).setState(Pipeline.PipelineState.OPEN).setLeaderId(dnOne.getUuid()).setNodes(Arrays.asList(dnOne, dnTwo, dnThree)).build();
    final Pipeline pipelineTwo = Pipeline.newBuilder().setId(PipelineID.randomId()).setType(ReplicationType.RATIS).setFactor(ReplicationFactor.THREE).setState(Pipeline.PipelineState.OPEN).setLeaderId(dnFour.getUuid()).setNodes(Arrays.asList(dnFour, dnFive, dnSix)).build();
    Mockito.when(containerClient.getContainerWithPipeline(1L)).thenReturn(new ContainerWithPipeline(null, pipelineTwo));
    final OmVolumeArgs volumeArgs = OmVolumeArgs.newBuilder().setVolume("volumeOne").setAdminName("admin").setOwnerName("admin").build();
    TestOMRequestUtils.addVolumeToOM(metadataManager, volumeArgs);
    final OmBucketInfo bucketInfo = OmBucketInfo.newBuilder().setVolumeName("volumeOne").setBucketName("bucketOne").build();
    TestOMRequestUtils.addBucketToOM(metadataManager, bucketInfo);
    final OmKeyLocationInfo keyLocationInfo = new OmKeyLocationInfo.Builder().setBlockID(new BlockID(1L, 1L)).setPipeline(pipelineOne).setOffset(0).setLength(256000).build();
    final OmKeyInfo keyInfo = new OmKeyInfo.Builder().setVolumeName("volumeOne").setBucketName("bucketOne").setKeyName("keyOne").setOmKeyLocationInfos(Collections.singletonList(new OmKeyLocationInfoGroup(0, Collections.singletonList(keyLocationInfo)))).setCreationTime(Time.now()).setModificationTime(Time.now()).setDataSize(256000).setReplicationType(ReplicationType.RATIS).setReplicationFactor(ReplicationFactor.THREE).setAcls(Collections.emptyList()).build();
    TestOMRequestUtils.addKeyToOM(metadataManager, keyInfo);
    final OmKeyArgs.Builder keyArgs = new OmKeyArgs.Builder().setVolumeName("volumeOne").setBucketName("bucketOne").setKeyName("keyOne");
    keyArgs.setRefreshPipeline(false);
    final OmKeyInfo oldKeyInfo = manager.lookupFile(keyArgs.build(), "test");
    final OmKeyLocationInfo oldBlockLocation = oldKeyInfo.getLatestVersionLocations().getBlocksLatestVersionOnly().get(0);
    Assert.assertEquals(1L, oldBlockLocation.getContainerID());
    Assert.assertEquals(1L, oldBlockLocation.getBlockID().getLocalID());
    Assert.assertEquals(pipelineOne.getId(), oldBlockLocation.getPipeline().getId());
    Assert.assertTrue(oldBlockLocation.getPipeline().getNodes().contains(dnOne));
    Assert.assertTrue(oldBlockLocation.getPipeline().getNodes().contains(dnTwo));
    Assert.assertTrue(oldBlockLocation.getPipeline().getNodes().contains(dnThree));
    keyArgs.setRefreshPipeline(true);
    final OmKeyInfo newKeyInfo = manager.lookupFile(keyArgs.build(), "test");
    final OmKeyLocationInfo newBlockLocation = newKeyInfo.getLatestVersionLocations().getBlocksLatestVersionOnly().get(0);
    Assert.assertEquals(1L, newBlockLocation.getContainerID());
    Assert.assertEquals(1L, newBlockLocation.getBlockID().getLocalID());
    Assert.assertEquals(pipelineTwo.getId(), newBlockLocation.getPipeline().getId());
    Assert.assertTrue(newBlockLocation.getPipeline().getNodes().contains(dnFour));
    Assert.assertTrue(newBlockLocation.getPipeline().getNodes().contains(dnFive));
    Assert.assertTrue(newBlockLocation.getPipeline().getNodes().contains(dnSix));
}

