@Test
public void testProcessICR() throws IOException, NodeNotFoundException {
    Pipeline pipeline = getRandomPipeline();
    ReconPipelineManager pipelineManager = getPipelineManager();
    pipelineManager.addPipeline(pipeline);
    ContainerID containerID = new ContainerID(100L);
    ContainerInfo containerInfo = new ContainerInfo.Builder().setContainerID(containerID.getId()).setNumberOfKeys(10).setPipelineID(pipeline.getId()).setReplicationFactor(ONE).setOwner("test").setState(OPEN).setReplicationType(STAND_ALONE).build();
    ContainerWithPipeline containerWithPipeline = new ContainerWithPipeline(containerInfo, pipeline);
    StorageContainerServiceProvider scmServiceProviderMock = mock(StorageContainerServiceProvider.class);
    when(scmServiceProviderMock.getContainerWithPipeline(100L)).thenReturn(containerWithPipeline);
    DatanodeDetails datanodeDetails = randomDatanodeDetails();
    IncrementalContainerReportFromDatanode reportMock = mock(IncrementalContainerReportFromDatanode.class);
    when(reportMock.getDatanodeDetails()).thenReturn(datanodeDetails);
    IncrementalContainerReportProto containerReport = getIncrementalContainerReportProto(containerID, State.OPEN, datanodeDetails.getUuidString());
    when(reportMock.getReport()).thenReturn(containerReport);
    NodeManager nodeManagerMock = mock(NodeManager.class);
    ReconContainerManager containerManager = getContainerManager();
    ReconIncrementalContainerReportHandler recconIcr = new ReconIncrementalContainerReportHandler(nodeManagerMock, containerManager, scmServiceProviderMock);
    EventPublisher eventPublisherMock = mock(EventPublisher.class);
    recconIcr.onMessage(reportMock, eventPublisherMock);
    verify(nodeManagerMock, times(1)).addContainer(datanodeDetails, containerID);
    assertTrue(containerManager.exists(containerID));
    assertEquals(1, containerManager.getContainerReplicas(containerID).size());
}

