@Test
public void testInitialization() throws Exception {
    MultivaluedMap<String, String> headers = new MultivaluedHashMap<>();
    headers.putSingle("Content-Length", "123");
    headers.putSingle("Host", "123");
    headers.putSingle("X-AMZ-Content-Sha256", "Content-SHA");
    headers.putSingle("X-AMZ-Date", "123");
    headers.putSingle("Content-Type", "ozone/mpu");
    headers.putSingle(HeaderPreprocessor.ORIGINAL_CONTENT_TYPE, "streaming");
    String authHeader = "AWS4-HMAC-SHA256 Credential=AKIAJWFJK62WUTKNFJJA/20181009/us-east-1" + "/s3/aws4_request, " + "SignedHeaders=host;x-amz-content-sha256;x-amz-date;" + "content-type, " + "Signature" + "=db81b057718d7c1b3b8dffa29933099551c51d787b3b13b9e0f9ebed45982bf2";
    headers.putSingle("Authorization", authHeader);
    AuthorizationHeaderV4 parserAuthHeader = new AuthorizationHeaderV4(authHeader) {

        @Override
        public void validateDateRange() throws OS3Exception {
        }
    };
    MultivaluedMap<String, String> queryParameters = new MultivaluedHashMap<>();
    UriInfo uriInfo = Mockito.mock(UriInfo.class);
    Mockito.when(uriInfo.getQueryParameters()).thenReturn(queryParameters);
    Mockito.when(uriInfo.getRequestUri()).thenReturn(new URI("http://localhost/buckets"));
    ContainerRequestContext mock = Mockito.mock(ContainerRequestContext.class);
    Mockito.when(mock.getHeaders()).thenReturn(headers);
    Mockito.when(mock.getMethod()).thenReturn("GET");
    Mockito.when(mock.getUriInfo()).thenReturn(uriInfo);
    AWSV4SignatureProcessor parser = new AWSV4SignatureProcessor() {

        @Override
        void validateSignedHeader(String header, String headerValue) throws OS3Exception {
            super.validateSignedHeader(header, headerValue);
        }
    };
    parser.setV4Header(parserAuthHeader);
    parser.setContext(mock);
    parser.init();
    Assert.assertTrue("the ozone/mpu header is not changed back before signature processing", parser.buildCanonicalRequest().contains("content-type:streaming"));
    Assert.assertEquals("String to sign is invalid", "AWS4-HMAC-SHA256\n" + "123\n" + "20181009/us-east-1/s3/aws4_request\n" + "21478b9cf7d628717e9029a93c4ddc35bb38cf50669ada529b94673b23ff23e2", parser.getStringToSign());
}

